// Default-construct add_torrent_params and seed a few simple fields to exercise code paths
libtorrent::add_torrent_params *params = new libtorrent::add_torrent_params();

// Populate a few trivial fields with fuzz data to increase coverage without heavy allocations
std::string save = FUZZ_PARAM_STR();
params->save_path = save; // commonly required by add_torrent later, safe to set here
params->name = FUZZ_PARAM_STR();
params->max_uploads = int(*FUZZ_PARAM(unsigned int) % 512) - 1;        // may be -1 (unlimited)
params->max_connections = int(*FUZZ_PARAM(unsigned int) % 1024) - 1;  // may be -1 (unlimited)

// Mark ownership for safe destruction later
FUZZ_SET_ATTR_INT(params, "owns", 1);
// Validation: params is a non-null, heap-allocated, default-initialized object ready for use.

// Destructor harness for user-managed add_torrent_params
// Ensure we only delete objects we created
int owns = FUZZ_GET_ATTR_INT(params, "owns");
if (!owns) {
    // Unknown ownership; avoid double free or invalid delete
    FUZZ_BAIL();
}

// Invoke destructor by deleting the heap allocation
delete params;
// Validation: object is deleted exactly once when marked as owned; no outputs returned.

// Prepare source with some fuzz content to exercise assignment paths
src->save_path = FUZZ_PARAM_STR();
src->name = FUZZ_PARAM_STR();
src->max_uploads = int(*FUZZ_PARAM(unsigned int) % 512) - 1;
src->max_connections = int(*FUZZ_PARAM(unsigned int) % 1024) - 1;

// Randomly choose copy vs. move assignment (avoid self-move)
bool do_move = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
if (do_move && dst != src) {
    *dst = std::move(*src); // move assignment overload
    FUZZ_SET_ATTR_INT(dst, "assigned_kind", 1); // 1 = move
} else {
    *dst = *src; // copy assignment overload
    FUZZ_SET_ATTR_INT(dst, "assigned_kind", 2); // 2 = copy
}

// Preserve ownership attribute on dst if either had it set
int owns_dst = FUZZ_GET_ATTR_INT(dst, "owns");
int owns_src = FUZZ_GET_ATTR_INT(src, "owns");
if (!owns_dst && owns_src) FUZZ_SET_ATTR_INT(dst, "owns", 1);

// Return both objects back to the pool as they remain valid after copy/move
// Validation: exercises both copy and move operators; avoids self-move; retains object ownership attributes.

// Optionally toggle a few fields to vary contains_resume_data() outcome
// (safe, lightweight fields)
params->active_time = int(*FUZZ_PARAM(unsigned int) % 100000);
params->finished_time = int(*FUZZ_PARAM(unsigned int) % 100000);
params->seeding_time = int(*FUZZ_PARAM(unsigned int) % 100000);

// Call the utility under test
bool has = libtorrent::aux::contains_resume_data(*params);

// Record the result for potential downstream checks
FUZZ_SET_ATTR_INT(params, "has_resume_data", has ? 1 : 0);

// Keep params alive by returning it as an output
// Validation: invokes const inspector on a live params object and records result as an attribute.

// Compose a valid IPv4 dotted-quad from random bytes
unsigned int rnd = *FUZZ_PARAM(unsigned int);
unsigned int a = (rnd >> 24) & 0xffu;
unsigned int b = (rnd >> 16) & 0xffu;
unsigned int c = (rnd >> 8)  & 0xffu;
unsigned int d = (rnd)       & 0xffu;
std::string ip = std::to_string(a) + "." + std::to_string(b) + "." + std::to_string(c) + "." + std::to_string(d);
// Constrain prefix length to [0, 32]
unsigned short pref = static_cast<unsigned short>(*FUZZ_PARAM(unsigned int) % 33u);
libtorrent::network_v4 *net = nullptr;
try {
    libtorrent::address_v4 addr = libtorrent::make_address_v4(ip);
    libtorrent::network_v4 nw = libtorrent::make_network_v4(addr, pref);
    // Allocate the output object (non-null per fuzzer contract)
    net = new libtorrent::network_v4(nw);
} catch (...) {
    // Parsing or construction failed (should be rare since we constrain inputs)
    FUZZ_BAIL();
}
// Validation: IPv4 string and prefix are constrained; on success we return a non-null network_v4*.

// Build a valid IPv4 address string from random bytes
unsigned int r = *FUZZ_PARAM(unsigned int);
unsigned int a = (r >> 24) & 0xffu;
unsigned int b = (r >> 16) & 0xffu;
unsigned int c = (r >> 8)  & 0xffu;
unsigned int d = (r)       & 0xffu;
std::string ip4 = std::to_string(a) + "." + std::to_string(b) + "." + std::to_string(c) + "." + std::to_string(d);
libtorrent::address_v6 *mapped6 = nullptr;
try {
    libtorrent::address_v4 v4 = libtorrent::make_address_v4(ip4);
    // Use the address_v6 helper to construct an IPv4-mapped IPv6
    libtorrent::address_v6 v6 = libtorrent::address_v6::v4_mapped(v4);
    FUZZ_ASSERT(v6.is_v4_mapped(), "result must be an IPv4-mapped IPv6 address");
    FUZZ_ASSERT(v6.to_v4() == v4, "mapped address must round-trip to original IPv4");
    mapped6 = new libtorrent::address_v6(v6);
} catch (...) {
    FUZZ_BAIL();
}
// Validation: we map a valid IPv4 into IPv6, assert v4-mapped property and round-trip, and return non-null address_v6*.

// Randomly choose to generate IPv4 or IPv6 textual address
bool use_v4 = ((*FUZZ_PARAM(unsigned int)) & 1u) == 0u;
std::string text;
if (use_v4) {
    unsigned int rnd = *FUZZ_PARAM(unsigned int);
    unsigned int a = (rnd >> 24) & 0xffu;
    unsigned int b = (rnd >> 16) & 0xffu;
    unsigned int c = (rnd >> 8)  & 0xffu;
    unsigned int d = (rnd)       & 0xffu;
    text = std::to_string(a) + "." + std::to_string(b) + "." + std::to_string(c) + "." + std::to_string(d);
} else {
    // Build a fully expanded IPv6 (8 hex groups)
    unsigned int r1 = *FUZZ_PARAM(unsigned int);
    unsigned int r2 = *FUZZ_PARAM(unsigned int);
    unsigned int r3 = *FUZZ_PARAM(unsigned int);
    unsigned int r4 = *FUZZ_PARAM(unsigned int);
    unsigned short h[8];
    h[0] = static_cast<unsigned short>(r1 & 0xffffu);
    h[1] = static_cast<unsigned short>((r1 >> 16) & 0xffffu);
    h[2] = static_cast<unsigned short>(r2 & 0xffffu);
    h[3] = static_cast<unsigned short>((r2 >> 16) & 0xffffu);
    h[4] = static_cast<unsigned short>(r3 & 0xffffu);
    h[5] = static_cast<unsigned short>((r3 >> 16) & 0xffffu);
    h[6] = static_cast<unsigned short>(r4 & 0xffffu);
    h[7] = static_cast<unsigned short>((r4 >> 16) & 0xffffu);
    std::ostringstream oss; oss << std::hex;
    for (int i = 0; i < 8; ++i) { if (i) oss << ":"; oss << std::nouppercase << h[i]; }
    text = oss.str();
}
libtorrent::address *addr = nullptr;
try {
    libtorrent::address a = libtorrent::make_address(text);
    if (use_v4) {
