        case 0: {
            // integer
            long long v = static_cast<long long>(*FUZZ_PARAM(unsigned int));
            *entry = libtorrent::entry::integer_type(v);
            break;
        }
        case 1: {
            // string (bound length)
            std::string s = FUZZ_PARAM_STR();
            if (s.size() > 128) s.resize(128);
            *entry = s; // entry(string)
            break;
        }
        case 2: {
            // small list of ints/strings
            libtorrent::entry::list_type lst;
            int n = static_cast<int>(*FUZZ_PARAM(unsigned int) % 4); // up to 3 elements
            for (int i = 0; i < n; ++i) {
                if ((i & 1) == 0) lst.emplace_back(libtorrent::entry::integer_type(static_cast<long long>(*FUZZ_PARAM(unsigned int))));
                else {
                    std::string s = FUZZ_PARAM_STR();
                    if (s.size() > 64) s.resize(64);
                    lst.emplace_back(s);
