        case 3: default: {
            // small dictionary of short keys -> ints/strings
            libtorrent::entry::dictionary_type dict;
            int n = static_cast<int>(*FUZZ_PARAM(unsigned int) % 4); // up to 3 pairs
            for (int i = 0; i < n; ++i) {
                std::string key = FUZZ_PARAM_STR();
                if (key.size() > 8) key.resize(8);
