                    dict.emplace(std::move(key), libtorrent::entry(static_cast<libtorrent::entry::integer_type>(static_cast<long long>(*FUZZ_PARAM(unsigned int)))));
                } else {
                    std::string val = FUZZ_PARAM_STR();
                    if (val.size() > 64) val.resize(64);
                    dict.emplace(std::move(key), libtorrent::entry(val));
                }
            }
            *entry = std::move(dict);
            break;
        }
    }

    // Prepare an output sink and invoke bencode
    std::vector<char> buf;
    buf.reserve(1024);
    auto out_it = std::back_inserter(buf);

    int written = libtorrent::bencode(out_it, *entry);

    // Basic properties to assert: positive length and consistent return value
    if (written <= 0) { FUZZ_BAIL(); }
    FUZZ_ASSERT(written == static_cast<int>(buf.size()), "bencode() byte count must equal buffer size");

