import random
import string
from typing import List

# Data type: generic string
# We generate a reasonably small, diverse UTF-8 string to seed fuzz stubs that
# consume FUZZ_PARAM_STR(). We aim for strings that can act as URLs, file paths,
# hostnames, PEM-like blobs, HTTP headers, XML/JSON fragments, or plain text.
# The output is bytes, length <= 4096.

_WORDS = [
    "alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta",
    "iota", "kappa", "lambda", "mu", "nu", "xi", "omicron", "pi", "rho",
    "sigma", "tau", "upsilon", "phi", "chi", "psi", "omega",
    "example", "tracker", "announce", "node", "dht", "torrent", "libtorrent",
    "seed", "peer", "http", "https", "udp", "tcp", "ipv4", "ipv6",
]

_URL_SCHEMES = ["http", "https"]
_TLDS = ["com", "org", "net", "io", "local", "example"]

_XML_SAFE_TEXT = string.ascii_letters + string.digits + " _-:.\/"  # no quotes/angles
_HEADER_CHARS = string.ascii_letters + string.digits + "-_.:/?&=%+;,@[]"  # ok for headers/urls

def _rand_hostname(r: random.Random) -> str:
    labels = []
    n = r.randint(1, 4)
    for _ in range(n):
        lab_len = r.randint(1, 10)
        lab = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(lab_len))
        # labels cannot start/end with hyphen ideally
        if lab[0] == '-':
            lab = 'a' + lab[1:]
        if lab[-1] == '-':
            lab = lab[:-1] + 'z'
        labels.append(lab)
    tld = r.choice(_TLDS)
    return '.'.join(labels + [tld])

def _rand_path(r: random.Random) -> str:
    depth = r.randint(0, 4)
    parts = []
    for _ in range(depth):
        seg_len = r.randint(1, 12)
        seg = ''.join(r.choice(string.ascii_lowercase + string.digits + "-_") for _ in range(seg_len))
        parts.append(seg)
    return "/" + "/".join(parts) if parts else "/"

def _rand_query(r: random.Random) -> str:
    if r.random() < 0.4:
        return ""
    pairs = []
    for _ in range(r.randint(1, 4)):
        k = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(1, 8)))
        v = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(0, 12)))
        pairs.append(f"{k}={v}")
    return "?" + "&".join(pairs)

def _make_url(r: random.Random) -> str:
    scheme = r.choice(_URL_SCHEMES)
    host = _rand_hostname(r)
    if r.random() < 0.3:
        port = f":{r.randint(1, 65535)}"
    else:
        port = ""
    path = _rand_path(r)
    query = _rand_query(r)
    return f"{scheme}://{host}{port}{path}{query}"

def _make_xml_snippet(r: random.Random) -> str:
    tag = r.choice(_WORDS)
    attr_k = r.choice(_WORDS)
    # value with safe characters
    val = ''.join(r.choice(_XML_SAFE_TEXT) for _ in range(r.randint(1, 20)))
    body = ' '.join(r.choice(_WORDS) for _ in range(r.randint(0, 5)))
    if r.random() < 0.3:
        decl = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
    else:
        decl = ""
    return f"{decl}<{tag} {attr_k}=\"{val}\">{body}</{tag}>"

def _make_pem_blob(r: random.Random) -> str:
    # Simple PEM-like text
    lines: List[str] = []
    lines.append("-----BEGIN CERTIFICATE-----")
    for _ in range(r.randint(1, 6)):
        ln = ''.join(r.choice(string.ascii_letters + string.digits + "+/=") for _ in range(r.randint(16, 64)))
        lines.append(ln)
    lines.append("-----END CERTIFICATE-----")
    return "\n".join(lines)

def _make_header_line(r: random.Random) -> str:
    k = ''.join(r.choice(string.ascii_letters + "-") for _ in range(r.randint(2, 12)))
    v = ''.join(r.choice(_HEADER_CHARS + ' ') for _ in range(r.randint(1, 40))).strip()
    return f"{k}: {v}"

def _make_path(r: random.Random) -> str:
    root = "/" if r.random() < 0.7 else ""
    parts = [_rand_path(r).strip('/')]
    # additional random filename
    fname = ''.join(r.choice(string.ascii_letters + string.digits + "-_.") for _ in range(r.randint(3, 12)))
    parts.append(fname)
    return root + '/'.join(p for p in parts if p)

def _make_plain(r: random.Random) -> str:
    # Generic alphanumeric text
    words = [r.choice(_WORDS) for _ in range(r.randint(1, 8))]
    return ' '.join(words)

def _make_query_string(r: random.Random) -> str:
    # Looks like tracker query
    info = ''.join(r.choice('0123456789abcdef') for _ in range(40))
    peer = ''.join(r.choice('0123456789abcdef') for _ in range(40))
    return f"info_hash={info}&peer_id={peer}&port={r.randint(1024,65535)}&uploaded=0&downloaded=0&left=0"

def _make_ipv6_endpoint(r: random.Random) -> str:
    ws = [f"{r.randint(0, 0xFFFF):x}" for _ in range(8)]
    return f"[{':'.join(ws)}]:{r.randint(0,65535)}"

def _assemble_multipart(r: random.Random) -> str:
    # Join a few different shapes with newlines to increase coverage
    parts = []
    generators = [_make_url, _make_xml_snippet, _make_pem_blob, _make_header_line,
                  _make_path, _make_plain, _make_query_string, _make_ipv6_endpoint]
    r.shuffle(generators)
    for gen in generators[:r.randint(2, 5)]:
        try:
            parts.append(gen(r))
        except Exception:
            pass
    return "\n".join(parts)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a family of strings to produce
    choice = r.randint(0, 9)
    if choice == 0:
        s = _make_url(r)
    elif choice == 1:
        s = _make_xml_snippet(r)
    elif choice == 2:
        s = _make_pem_blob(r)
    elif choice == 3:
        s = _make_header_line(r)
    elif choice == 4:
        s = _make_path(r)
    elif choice == 5:
        s = _make_plain(r)
    elif choice == 6:
        s = _make_query_string(r)
    elif choice == 7:
        s = _make_ipv6_endpoint(r)
    else:
        s = _assemble_multipart(r)

    # Occasionally prefix/suffix with whitespace to exercise trimming paths
    if r.random() < 0.3:
        s = (" " * r.randint(0, 3)) + s + ("\n\t" * r.randint(0, 2))

    # Ensure we stay within 4096 bytes
    b = s.encode('utf-8', errors='ignore')
    if len(b) > 4096:
        b = b[:4096]
    return b

import random
import string
from urllib.parse import quote

# This generator focuses on producing valid and interesting URL strings that exercise
# libtorrent URL and tracker/web-seed related paths used by the target fuzz stubs.
# The buffer returned is a UTF-8 encoded URL (bytes).
#
# Strategy:
# - Prefer valid HTTP/HTTPS URLs with varying hosts, ports, paths, queries and fragments.
# - Sometimes generate tracker-like URLs (/announce, /scrape) with conventional query keys.
# - Sometimes generate web-seed-like URLs (ending with filename or torrent-like paths).
# - Inject percent-encoding, IPv4/IPv6 hosts, userinfo, and edge-case ports.
# - Keep result length reasonable (< 512 bytes).

SCHEMES = ["http", "https"]
TLDS = ["com", "org", "net", "io", "test", "example"]
TRACKER_PATHS = [
    "/announce",
    "/tracker/announce",
    "/announce.php",
    "/announce/full",
]
SCRAPE_PATHS = [
    "/scrape",
    "/tracker/scrape",
]
WEB_SEED_PATHS = [
    "/files/ubuntu.iso",
    "/content/big.bin",
    "/data/payload",
    "/pieces/0001",
]
PARAM_KEYS = [
    "info_hash", "peer_id", "port", "uploaded", "downloaded", "left",
    "compact", "event", "numwant", "key", "trackerid", "supportcrypto",
]
EVENT_VALUES = ["started", "stopped", "completed", "paused", "none"]

SAFE_CHARS = string.ascii_letters + string.digits + "-._~"
HOST_CHARS = string.ascii_lowercase + string.digits + "-"


def _rand_label(rng: random.Random, min_len=3, max_len=10):
    n = rng.randint(min_len, max_len)
    s = ''.join(rng.choice(HOST_CHARS) for _ in range(n))
    s = s.strip('-') or 'host'
    return s


def _rand_hostname(rng: random.Random):
    # Sometimes IPv4, sometimes domain, sometimes IPv6 literal
    kind = rng.randint(0, 4)
    if kind == 0:
        # IPv4
        return f"{rng.randint(1, 223)}.{rng.randint(0, 255)}.{rng.randint(0, 255)}.{rng.randint(1, 254)}"
    elif kind == 1:
        # IPv6 literal
        def hextet():
            return format(rng.randint(0, 0xFFFF), 'x')
        blocks = [hextet() for _ in range(rng.randint(2, 8))]
        # compress with :: sometimes
        if len(blocks) >= 3 and rng.random() < 0.5:
            cut = rng.randint(1, len(blocks)-1)
            left = blocks[:cut]
            right = blocks[cut:]
            core = ":".join(left) + "::" + ":".join(right)
        else:
            core = ":".join(blocks)
        return f"[{core}]"
    else:
        # domain
        labels = [_rand_label(rng) for _ in range(rng.randint(2, 4))]
        tld = rng.choice(TLDS)
        return ".".join(labels + [tld])


def _maybe_userinfo(rng: random.Random):
    if rng.random() < 0.25:
        user = ''.join(rng.choice(SAFE_CHARS) for _ in range(rng.randint(3, 8)))
        if rng.random() < 0.5:
            pwd = ''.join(rng.choice(SAFE_CHARS) for _ in range(rng.randint(3, 8)))
            return f"{user}:{pwd}@"
        return f"{user}@"
    return ""


def _rand_port(rng: random.Random):
    # Often plausible ports, sometimes random high port
    if rng.random() < 0.5:
        return rng.choice([80, 443, 6969, 8080, 8443, 1337])
    return rng.randint(1024, 65535)


def _rand_path_segment(rng: random.Random):
    # produce a segment with safe and some percent-encoded chars
    seg_raw = ''.join(rng.choice(SAFE_CHARS + ' _') for _ in range(rng.randint(3, 12)))
    # percent-encode spaces and random characters
    enc = ''.join(quote(ch, safe=SAFE_CHARS) for ch in seg_raw)
    return enc.replace('%20', '+') if rng.random() < 0.3 else enc


def _rand_query(rng: random.Random, tracker_like=True):
    pairs = []
    kcount = rng.randint(1, 6)
    for _ in range(kcount):
        if tracker_like and rng.random() < 0.8:
            k = rng.choice(PARAM_KEYS)
        else:
            k = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 10)))
        if k == "info_hash":
            # 20-byte urlencoded value
            raw = bytes(rng.getrandbits(8) for _ in range(20))
            v = quote(raw.decode('latin1'), safe='')
        elif k == "peer_id":
            raw = bytes(rng.getrandbits(8) for _ in range(20))
            v = quote(raw.decode('latin1'), safe='')
        elif k in ("uploaded", "downloaded", "left", "numwant", "port"):
            v = str(rng.randint(0, 10_000_000))
        elif k == "event":
            v = rng.choice(EVENT_VALUES)
        else:
            val = ''.join(rng.choice(SAFE_CHARS) for _ in range(rng.randint(3, 12)))
            v = quote(val, safe=SAFE_CHARS)
        pairs.append(f"{k}={v}")
    return "&".join(pairs)


def _build_tracker_url(rng: random.Random):
    scheme = rng.choice(SCHEMES)
    userinfo = _maybe_userinfo(rng)
    host = _rand_hostname(rng)
    port = _rand_port(rng)
    path = rng.choice(TRACKER_PATHS + SCRAPE_PATHS)
    # maybe add extra segments
    if rng.random() < 0.4:
        path += "/" + "/".join(_rand_path_segment(rng) for _ in range(rng.randint(1, 3)))
    q = _rand_query(rng, tracker_like=True) if rng.random() < 0.9 else ""
    frag = ''
    if rng.random() < 0.2:
        frag = '#'+_rand_path_segment(rng)
    url = f"{scheme}://{userinfo}{host}:{port}{path}"
    if q:
        url += '?' + q
    url += frag
    return url


def _build_webseed_url(rng: random.Random):
    scheme = rng.choice(SCHEMES)
    userinfo = _maybe_userinfo(rng)
    host = _rand_hostname(rng)
    port = _rand_port(rng) if rng.random() < 0.7 else None
    base_parts = ["", *(_rand_path_segment(rng) for _ in range(rng.randint(0, 3)))]
    base = "/".join(base_parts) if base_parts else "/"
    # choose predefined web seed-ish path or custom
    path = rng.choice(WEB_SEED_PATHS) if rng.random() < 0.6 else "/" + "/".join(
        _rand_path_segment(rng) for _ in range(rng.randint(1, 4))
    )
    q = _rand_query(rng, tracker_like=False) if rng.random() < 0.5 else ""
    url = f"{scheme}://{userinfo}{host}"
    if port is not None:
        url += f":{port}"
    # ensure a leading slash once
    if not path.startswith('/'):
        path = '/' + path
    if base and base != "/":
        if not base.startswith('/'):
            base = '/' + base
        # avoid double slashes
        if base.endswith('/') and path.startswith('/'):
            path = path[1:]
        url += base
    url += path
    if q:
        url += '?' + q
    return url


def _build_absolute_url(rng: random.Random):
    # Mix between tracker-style and webseed-style
    if rng.random() < 0.6:
        return _build_tracker_url(rng)
    return _build_webseed_url(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # choose mode
    mode = rng.random()
    if mode < 0.15:
        # Minimal canonical tracker URL
        url = "http://example.com/announce"
    elif mode < 0.3:
        # Scrape URL
        url = "http://tracker.example.org/scrape"
    else:
        url = _build_absolute_url(rng)

    # length guard (<= 512)
    if len(url) > 512:
        url = url[:512]

    return url.encode('utf-8')

import random
import string
from typing import List, Tuple, Union

# This generator produces valid bencoded data tailored to exercise libtorrent::bdecode_node
# and related functions. It focuses on constructing dictionaries and lists with a mix of
# integers, byte strings, nested lists/dicts, and typical BitTorrent-like keys to reach
# code paths that search for strings/ints/lists/dicts, and to allow parse_tracker_response
# style payloads. It keeps output <= 4096 bytes.

BStr = bytes
BVal = Union[int, BStr, List['BVal'], Tuple[str, 'BVal'], dict]

# ------------------------- bencoding helpers -------------------------

def bencode_int(n: int) -> bytes:
    return b"i" + str(int(n)).encode('ascii') + b"e"

def bencode_bytes(b: bytes) -> bytes:
    return str(len(b)).encode('ascii') + b":" + b

def bencode_str(s: str) -> bytes:
    # treat as byte string
    return bencode_bytes(s.encode('utf-8', errors='ignore'))

def bencode_list(lst: List[BVal]) -> bytes:
    out = [b"l"]
    for v in lst:
        out.append(bencode_any(v))
    out.append(b"e")
    return b''.join(out)

def bencode_dict(d: dict) -> bytes:
    # keys must be byte strings sorted lexicographically
    out = [b"d"]
    for k in sorted(d.keys(), key=lambda x: x.encode('utf-8')):
        out.append(bencode_str(k))
        out.append(bencode_any(d[k]))
    out.append(b"e")
    return b''.join(out)

def bencode_any(v: BVal) -> bytes:
    if isinstance(v, int):
        return bencode_int(v)
    if isinstance(v, bytes):
        return bencode_bytes(v)
    if isinstance(v, str):
        return bencode_str(v)
    if isinstance(v, list):
        return bencode_list(v)
    if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], str):
        # key-value pair, encode as {k: v}
        return bencode_dict({v[0]: v[1]})
    if isinstance(v, dict):
        return bencode_dict(v)
    # fallback
    return bencode_str(str(v))

# ------------------------- content builders -------------------------

def rand_ascii(rng: random.Random, min_len=0, max_len=16) -> str:
    n = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + "-_./"
    return ''.join(rng.choice(alphabet) for _ in range(n))

def rand_bytes(rng: random.Random, min_len=0, max_len=32) -> bytes:
    n = rng.randint(min_len, max_len)
    return bytes(rng.getrandbits(8) for _ in range(n))

# Build a value likely to be useful for bdecode_node list/dict/int/string paths

def build_random_value(rng: random.Random, depth: int) -> BVal:
    if depth <= 0:
        # leaf: int or string
        return rng.choice([rng.randint(-2**31, 2**31-1), rand_ascii(rng, 0, 24)])
    choice = rng.random()
    if choice < 0.25:
        return rng.randint(-2**31, 2**31-1)
    elif choice < 0.50:
        return rand_ascii(rng, 0, 48)
    elif choice < 0.75:
        # list
        cnt = rng.randint(0, 6)
        return [build_random_value(rng, depth-1) for _ in range(cnt)]
    else:
        # dict
        cnt = rng.randint(0, 6)
        d = {}
        for _ in range(cnt):
            d[rand_ascii(rng, 1, 12)] = build_random_value(rng, depth-1)
        return d

# Build a tracker-like response dictionary to exercise parse_tracker_response

def build_tracker_response(rng: random.Random) -> dict:
    # Create peers list in multiple encodings and standard fields
    peers_compact = rand_bytes(rng, 0, 120)  # may be empty; valid bencoded bytes
    peers6_compact = rand_bytes(rng, 0, 150)
    peers_list = []
    for _ in range(rng.randint(0, 5)):
        host = rand_ascii(rng, 5, 12) + ".example.com"
        pid = rand_bytes(rng, 20, 20)
        port = rng.randint(1, 65535)
        peers_list.append({"peer id": pid, "ip": host, "port": port})
    resp = {
        "interval": rng.randint(30, 3600),
        "min interval": rng.randint(1, 300),
        "complete": rng.randint(0, 5000),
        "incomplete": rng.randint(0, 5000),
        # Both forms: list and compact
        "peers": peers_list if rng.random() < 0.5 else peers_compact,
    }
    if rng.random() < 0.5:
        resp["peers6"] = peers6_compact
    if rng.random() < 0.3:
        resp["tracker id"] = rand_ascii(rng, 4, 16)
    if rng.random() < 0.2:
        resp["failure reason"] = rand_ascii(rng, 8, 24)
    if rng.random() < 0.2:
        resp["warning message"] = rand_ascii(rng, 8, 24)
    return resp

# Build a plausible .torrent info dictionary to exercise torrent_info paths

def build_info_dict(rng: random.Random) -> dict:
    # Either single-file or multi-file
    piece_len = rng.choice([16384, 32768, 65536, 262144])
    pieces_count = rng.randint(1, 64)
    pieces = rand_bytes(rng, 20 * pieces_count, 20 * pieces_count)
    if rng.random() < 0.5:
        # single-file
        info = {
            "name": rand_ascii(rng, 4, 20),
            "length": rng.randint(0, 5_000_000),
            "piece length": piece_len,
            "pieces": pieces,
        }
    else:
        files = []
        for _ in range(rng.randint(1, 6)):
            files.append({
                "length": rng.randint(0, 2_000_000),
                "path": [rand_ascii(rng, 1, 10) for __ in range(rng.randint(1, 3))]
            })
        info = {
            "name": rand_ascii(rng, 4, 20),
            "files": files,
            "piece length": piece_len,
            "pieces": pieces,
        }
    # Occasionally set private flag or v2-like fields (still valid bencode even if ignored)
    if rng.random() < 0.2:
        info["private"] = rng.randint(0, 1)
    return info

# Build a resume-data-like dictionary for read_resume_data() path

def build_resume_data(rng: random.Random) -> dict:
    rd = {
        "file-format": "libtorrent resume file",
        "file-version": 1,
        "info-hash": rand_bytes(rng, 20, 20),
        "name": rand_ascii(rng, 4, 16),
        "pieces": rand_bytes(rng, 0, 128),
        "total_uploaded": rng.randint(0, 10_000_000),
        "total_downloaded": rng.randint(0, 10_000_000),
        "active_time": rng.randint(0, 100000),
    }
    # Optionally include trackers
    if rng.random() < 0.6:
        rd["trackers"] = [["http://" + rand_ascii(rng, 4, 10) + ".tracker/announce"]]
    return rd

# Build a rich root dictionary combining useful structures

def build_root_bencode(rng: random.Random) -> dict:
    root: dict = {}
    # Ensure we have top-level dictionary for many tests
    root["aa"] = 1  # int for dict_find_int
    root["bb"] = rand_ascii(rng, 3, 12)  # string for dict_find_string
    root["cc"] = [build_random_value(rng, 2) for _ in range(rng.randint(0, 4))]  # list
    # Nested structures so list_* and dict_* can find suitable nodes
    nested = {
        "l": [rand_ascii(rng, 1, 6), rng.randint(-9999, 9999), [1, 2, 3]],
        "d": {"k1": rand_ascii(rng, 2, 8), "k2": rng.randint(0, 1000)},
    }
    root["nested"] = nested

    # Add a plausible tracker response under a key
    if rng.random() < 0.8:
        root["tracker"] = build_tracker_response(rng)

    # Add a plausible torrent info dictionary in typical torrent layout
    if rng.random() < 0.8:
        info = build_info_dict(rng)
        root["info"] = info
        # Top-level torrent fields
        if rng.random() < 0.6:
            root["announce"] = "http://" + rand_ascii(rng, 5, 12) + ".tracker/announce"
        if rng.random() < 0.3:
            root["announce-list"] = [["http://" + rand_ascii(rng, 5, 12) + ".alt/announce"]]
        if rng.random() < 0.3:
            root["creation date"] = rng.randint(0, 2_000_000_000)
        if rng.random() < 0.3:
            root["comment"] = rand_ascii(rng, 4, 24)

    # Include a resume-data style blob (under an arbitrary key)
    if rng.random() < 0.7:
        root["rd"] = build_resume_data(rng)

    # Extra variety
    if rng.random() < 0.5:
        root["list"] = [rng.randint(-10, 10), rand_ascii(rng, 0, 8), {"inner": rng.randint(0, 5)}]

    return root

# ------------------------- public API -------------------------

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a mode: dictionary-root (most common and most useful here) or list-root
    mode = rng.random()
    if mode < 0.85:
        root = build_root_bencode(rng)
        data = bencode_dict(root)
    else:
        lst = [build_random_value(rng, 2) for _ in range(rng.randint(0, 6))]
        data = bencode_list(lst)

    # Keep size bounded; if too large, trim by reducing appended noise instead of corrupting bencode
    # If still too large, rebuild a smaller, simpler dictionary.
    if len(data) > 4096:
        # Rebuild simpler content deterministically based on seed variations
        rng2 = random.Random(seed ^ 0xA5A5)
        simple = {
            "info": build_info_dict(rng2),
            "tracker": build_tracker_response(rng2),
            "bb": rand_ascii(rng2, 3, 8),
            "aa": rng2.randint(0, 100),
        }
        data = bencode_dict(simple)
        if len(data) > 4096:
            # As last resort, emit a tiny valid integer dict
            data = bencode_dict({"a": 1, "b": "x"})

    return data
